mapper.select:
select * from sys_user where deleted = 0
and user_no like concat('%', #{userNo}, '%')
and real_name like concat('%', #{realName}, '%')
and department_id = #{departmentId}
and exists ( select 1 from sys_user_role ur join sys_role r on r.id = ur.role_id where ur.user_id = sys_user.id and r.role_code = #{roleCode} and r.deleted = 0 and r.status = 1 )
and status = #{status}
order by id desc limit #{offset}, #{pageSize}

select count(*) from sys_user where deleted = 0
and user_no like concat('%', #{userNo}, '%')
and real_name like concat('%', #{realName}, '%')
and department_id = #{departmentId}
and exists ( select 1 from sys_user_role ur join sys_role r on r.id = ur.role_id where ur.user_id = sys_user.id and r.role_code = #{roleCode} and r.deleted = 0 and r.status = 1 )
and status = #{status}

select * from sys_user where deleted = 0
and status = #{status}
order by id asc

mapper.update:
update sys_user
set password = #{password}
where id = #{id}
    and deleted = 0

update sys_user
set status = #{status}
where id = #{id}
    and deleted = 0

update sys_user
set last_login_at = now()
where id = #{id}

update sys_user
set credit_score = least(100, greatest(0, credit_score + #{scoreDelta})),
    violation_count = violation_count + #{violationDelta}
where id = #{id}
    and deleted = 0

update sys_user
set normal_reservation_streak = #{normalReservationStreak}
where id = #{id}
    and deleted = 0
